-- 382: Original BrillaPrep flashcards, batch flashcards-beta-001, part 2 of 5.
-- Curriculum-aligned revision content; not official WAEC or NaCCA examination material.
PRAGMA foreign_keys = ON;
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_mechanics_05', 'deck_sys_topic_mechanics', 'Which kinematic equation links displacement to initial velocity, acceleration and time?', 's = ut + ½at².', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_mechanics_06', 'deck_sys_topic_mechanics', 'Which kinematic equation does not involve time?', 'v² = u² + 2as.', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_mechanics_07', 'deck_sys_topic_mechanics', 'What is the SI unit of force?', 'The newton (N); 1 N = 1 kg·m/s², the force that gives a 1 kg mass an acceleration of 1 m/s².', NULL, NULL, 1);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_mechanics_08', 'deck_sys_topic_mechanics', 'What is the difference between speed and velocity?', 'Speed is a scalar quantity (magnitude only); velocity is a vector quantity (magnitude and direction).', NULL, NULL, 1);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_mechanics_09', 'deck_sys_topic_mechanics', 'Define linear momentum.', 'The product of a body’s mass and its velocity: p = mv. It is a vector with SI unit kg·m/s (equivalently N·s).', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_mechanics_10', 'deck_sys_topic_mechanics', 'What does the gradient of a velocity–time graph represent?', 'The acceleration of the body. (The area under the graph gives the displacement.)', NULL, 'Gradient = rate of change.', 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_electricity_01', 'deck_sys_topic_electricity', 'State Ohm’s law.', 'The current through a metallic conductor is directly proportional to the potential difference across it, provided temperature and other physical conditions remain constant: V = IR.', NULL, NULL, 1);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_electricity_02', 'deck_sys_topic_electricity', 'Define electric current and state its SI unit.', 'Current is the rate of flow of electric charge, I = Q/t; its SI unit is the ampere (A), where 1 A = 1 C/s.', NULL, NULL, 1);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_electricity_03', 'deck_sys_topic_electricity', 'What is the SI unit of electric charge?', 'The coulomb (C); 1 C = 1 A·s, the charge passing a point when a current of 1 A flows for 1 s.', NULL, NULL, 1);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_electricity_04', 'deck_sys_topic_electricity', 'Write the formula for electrical power in terms of current and voltage.', 'P = IV. Combined with Ohm’s law this also gives P = I²R and P = V²/R.', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_electricity_05', 'deck_sys_topic_electricity', 'What is the SI unit of resistance?', 'The ohm (Ω); 1 Ω = 1 V/A.', NULL, NULL, 1);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_electricity_06', 'deck_sys_topic_electricity', 'How do resistors combine in series?', 'Their resistances add: R_total = R₁ + R₂ + R₃ + …, and the same current flows through each resistor.', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_electricity_07', 'deck_sys_topic_electricity', 'How do resistors combine in parallel?', 'Their reciprocals add: 1/R_total = 1/R₁ + 1/R₂ + …, so the total resistance is less than the smallest branch resistance.', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_electricity_08', 'deck_sys_topic_electricity', 'Define the potential difference between two points.', 'The work done (energy transferred) per unit charge in moving charge between the two points: V = W/Q, measured in volts.', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_electricity_09', 'deck_sys_topic_electricity', 'What is the force on a charge q placed in an electric field E?', 'F = qE, in the direction of the field for a positive charge and opposite to it for a negative charge.', NULL, NULL, 3);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_electricity_10', 'deck_sys_topic_electricity', 'What is the force on a current-carrying conductor in a magnetic field?', 'F = BIL sin θ, where B is the magnetic flux density, I the current, L the conductor length and θ the angle between the conductor and the field; the force is maximum when θ = 90°.', NULL, NULL, 3);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_atomic_01', 'deck_sys_topic_atomic', 'Which subatomic particles make up an atom, and where is each found?', 'Protons and neutrons are packed in the tiny central nucleus; electrons occupy energy levels (shells) around the nucleus.', NULL, NULL, 1);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_atomic_02', 'deck_sys_topic_atomic', 'Define the atomic number, Z.', 'The number of protons in the nucleus of an atom. It identifies the element and equals the number of electrons in a neutral atom.', NULL, NULL, 1);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_atomic_03', 'deck_sys_topic_atomic', 'Define the mass number, A, and relate it to Z and N.', 'A is the total number of protons and neutrons in the nucleus: A = Z + N, where N is the number of neutrons.', NULL, NULL, 1);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_atomic_04', 'deck_sys_topic_atomic', 'What are isotopes?', 'Atoms of the same element (same atomic number Z) that have different numbers of neutrons and therefore different mass numbers; they share chemical properties but differ in mass.', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_atomic_05', 'deck_sys_topic_atomic', 'Give the relative charge and approximate relative mass of the proton, neutron and electron.', 'Proton: charge +1, mass ≈ 1; neutron: charge 0, mass ≈ 1; electron: charge −1, mass ≈ 1/1836 (effectively negligible).', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_atomic_06', 'deck_sys_topic_atomic', 'What does the Aufbau principle state about electron configuration?', 'Electrons fill orbitals in order of increasing energy — 1s, 2s, 2p, 3s, 3p, 4s, 3d, … — occupying the lowest available energy level first.', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_atomic_07', 'deck_sys_topic_atomic', 'Write the electron configuration of sodium (Na, Z = 11).', '1s² 2s² 2p⁶ 3s¹, or in shorthand [Ne] 3s¹.', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_atomic_08', 'deck_sys_topic_atomic', 'What does the Bohr model say about electrons in the hydrogen atom?', 'Electrons move in fixed energy levels (shells) labelled n = 1, 2, 3, … and absorb or emit energy only when they jump between levels.', NULL, NULL, 3);
